            requires
                self@ is Complete,
            ensures
                other.id() == self.id(),
                other@ is Complete,
        {
            unimplemented!()
        }

        #[verifier::external_body]
        pub proof fn lemma_is_complete_if_other_is(tracked &mut self, tracked other: &Self)
            requires
